import{c as t,Q as a,j as r,m as o}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"SwiftCache: Efficient LLM Serving for Multi-turn Conversations with Heterogeneous KV Cache Sharing","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.16135","title":"SwiftCache: Efficient LLM Serving for Multi-turn Conversations with Heterogeneous KV Cache Sharing","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2606.16135,"authors":["Jianmin Hu","Minxian Xu","Sa Wang","Chong Ma","Min Shen","Kejiang Ye","Lin Qu","Chengzhong Xu"],"domains":["cs.DC","KV cache"],"html":"https://arxiv.org/html/2606.16135v1","pdf_path":"pdfs/2606.16135.pdf","published_date":"2026-06-15T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-06-15-swiftcache-heterogeneous-kv-cache-sharing-2606-16135.md","filePath":"research/papers/2026-06-15-swiftcache-heterogeneous-kv-cache-sharing-2606-16135.md","lastUpdated":1785909234000}'),n={name:"research/papers/2026-06-15-swiftcache-heterogeneous-kv-cache-sharing-2606-16135.md"};function i(s,e,c,h,l,d){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="swiftcache-efficient-llm-serving-for-multi-turn-conversations-with-heterogeneous-kv-cache-sharing" tabindex="-1">SwiftCache: Efficient LLM Serving for Multi-turn Conversations with Heterogeneous KV Cache Sharing <a class="header-anchor" href="#swiftcache-efficient-llm-serving-for-multi-turn-conversations-with-heterogeneous-kv-cache-sharing" aria-label="Permalink to &quot;SwiftCache: Efficient LLM Serving for Multi-turn Conversations with Heterogeneous KV Cache Sharing&quot;">​</a></h1><p><strong>Authors</strong>: Jianmin Hu, Minxian Xu, Sa Wang, Chong Ma, Min Shen, Kejiang Ye, Lin Qu, Chengzhong Xu <strong>Published</strong>: June 15, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2606.16135" target="_blank" rel="noreferrer">https://arxiv.org/abs/2606.16135</a> · <a href="https://arxiv.org/html/2606.16135v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2606.16135 <strong>Categories</strong>: cs.DC <strong>PDF</strong>: <a href="https://arxiv.org/abs/2606.16135" target="_blank" rel="noreferrer">research/papers/pdfs/2606.16135.pdf</a> (15 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Multi-turn conversation is a fundamental scenario in LLM applications, widely used in chatbots and AI agents. As the conversation evolves, historical tokens accumulate continuously. Existing systems cache their key-value (KV) pairs to avoid redundant computation. However, limited GPU memory (HBM) capacity often forces these KV caches to be offloaded to CPU memory or SSD, making KV cache reloads increasingly costly in terms of latency as the context grows. Meanwhile, the constrained HBM capacity also limits the maximum inference length, thereby restricting the number of turns that can be supported in a conversation. To address these two challenges, we propose SwiftCache, a collaborative inference system that enables heterogeneous models to share underutilized GPU memory and NVLink bandwidth within a server. Specifically, models with low KV cache demand donate idle GPU memory to store the prefix cache of high-demand models, allowing cross-model KV cache sharing over NVLink and avoiding slow PCIe transfers. SwiftCache further reduces memory pressure by keeping only the KV cache of the currently active layer in local GPU memory, thereby enabling longer-context inference. Our experiments on real-world workloads show that SwiftCache reduces P99 time-to-first-token (TTFT) by up to 69% and extends maximum context length by up to 3.98x compared to vLLM and SGLang, with minimal interference to co-located models.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li><strong>異構 KV cache 共享</strong>：提出 SwiftCache 協作推論系統，讓同一伺服器內 KV cache 需求低的模型，將閒置 GPU HBM 捐出給高需求模型，透過 NVLink 跨模型共享 prefix cache，繞過速度慢的 PCIe 傳輸。</li><li><strong>逐層 active KV cache</strong>：任意時刻只在本地 GPU 記憶體保留「當前 active layer」的 KV cache，大幅降低 HBM 壓力，支援更長 context 推論。</li><li><strong>Multi-turn 場景優化</strong>：針對 chatbot / AI agent 多輪對話中 historical token 持續累積導致的延遲與長度限制，提出端到端系統解法。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>P99 TTFT（time-to-first-token）最高降低 <strong>69%</strong>（對比 vLLM 與 SGLang）。</li><li>最大支援 context 長度延伸最高 <strong>3.98×</strong>。</li><li>對同節點 co-located 模型的推論干擾最小。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>論文聚焦單一伺服器內 NVLink 拓撲，跨節點（multi-node）場景未覆蓋。</li><li>異構模型共存的排程策略複雜度在動態負載下的穩健性未深入評估。</li><li>實驗基準僅對比 vLLM 與 SGLang，未涵蓋其他 KV offloading 方案（如 InfiniGen、MagicPIG）。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>context-management / NLAH 原則</strong>：SwiftCache 的 prefix cache 共享機制，與 <code>context-management.md</code> 中「Right context &gt; more context」的 NLAH 原則在理念上呼應——都在解決 context 累積導致的記憶體/token 壓力；但 SwiftCache 是硬體層方案，workspace 的 prompt caching 是 API 層，域不同，⚠️ 不可直接類比為實作參考。</li><li><strong><code>core.md §PROPOSE 委派</code>（原 subagent-strategy.md） / KV cache 與 fan-out</strong>：多輪 AI agent 對話中 KV cache 累積問題，對應 <code>core.md §PROPOSE 委派</code> 委派決策中「讀取 ≥10 檔 → context rot」的場景；SwiftCache 的跨模型 cache 共享概念，可作為思考 multi-agent 工作流中 context 隔離與共享的理論背景，⚠️ 但 workspace 無對應基礎設施層可直接採用。</li><li><strong>unverified_success 閘門</strong>：論文以 P99 TTFT 等可量化指標作為驗證依據，符合 <code>core.md</code> TEST 階段「展示確定性輸出才升 verified」的精神，可作為 LLM serving 系統評估指標的參考案例。</li><li><strong>The Loop OBSERVE 階段</strong>：SwiftCache 針對 GPU HBM 容量限制做精準的問題定義（OBSERVE），再提出最小干預解（NVLink sharing），與 core.md PROPOSE「外科刀原則」結構相符，是論文寫作與系統設計方法論的良好示範，⚠️ 僅概念映射，非工具整合。</li></ul>',16)])])}const f=t(n,[["render",i]]);export{u as __pageData,f as default};
